import * as React from "react";
import { Calendar as CalendarIcon } from "lucide-react";
import type { DateRange } from "react-day-picker";

import { cn, formatFullDate } from "@blocks/ui/lib/utils";
import { Button } from "@blocks/ui/components/button";
import { Calendar } from "@blocks/ui/components/calendar";
import { Popover, PopoverContent, PopoverTrigger } from "@blocks/ui/components/popover";

export interface DateRangePickerProps {
  /** Visible label inside the trigger button when no range is selected. */
  label: string;
  /** Currently committed range (controlled). */
  value?: DateRange;
  /** Called when the user clicks "Apply". */
  onChange?: (range: DateRange | undefined) => void;
  /** Number of months shown side-by-side. Defaults to 2 (matches the design). */
  numberOfMonths?: number;
  /** Disable specific dates inside the calendar. */
  disabled?: React.ComponentProps<typeof Calendar>["disabled"];
  /** Trigger button width. */
  className?: string;
  /** Side of the popover relative to the trigger. */
  align?: "start" | "center" | "end";
}

function formatRange(range: DateRange | undefined): string | null {
  if (!range?.from) return null;
  if (!range.to) return formatFullDate(range.from, true);
  return `${formatFullDate(range.from, true)} – ${formatFullDate(range.to, true)}`;
}

/**
 * Two-month date-range picker with "Reset" / "Apply" footer.
 *
 * Visual reference: the date-range filter used in the parent app's
 * Localization → Translations table (e.g. "Create Date" filter).
 */
const DateRangePicker = React.forwardRef<HTMLButtonElement, DateRangePickerProps>(
  (
    { label, value, onChange, numberOfMonths = 2, disabled, className, align = "start" },
    ref,
  ) => {
    const [open, setOpen] = React.useState(false);
    /** Draft selection — only committed to `onChange` when "Apply" is pressed. */
    const [draft, setDraft] = React.useState<DateRange | undefined>(value);

    // Reset the draft whenever the popover (re)opens or external value changes.
    React.useEffect(() => {
      if (open) setDraft(value);
    }, [open, value]);

    const formatted = formatRange(value);

    return (
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button
            ref={ref}
            variant="outline"
            size="sm"
            className={cn("h-8 gap-2 rounded-full font-normal", className)}
          >
            <CalendarIcon className="h-4 w-4" />
            <span className="truncate">{formatted ?? label}</span>
          </Button>
        </PopoverTrigger>
        <PopoverContent align={align} className="w-auto p-0" sideOffset={6}>
          <Calendar
            mode="range"
            selected={draft}
            onSelect={setDraft}
            numberOfMonths={numberOfMonths}
            disabled={disabled}
            defaultMonth={value?.from ?? draft?.from ?? new Date()}
          />
          <div className="flex items-center justify-between gap-2 border-t border-border p-3">
            <Button
              variant="outline"
              size="sm"
              className="flex-1"
              onClick={() => {
                setDraft(undefined);
                onChange?.(undefined);
                setOpen(false);
              }}
            >
              Reset
            </Button>
            <Button
              size="sm"
              className="flex-1"
              onClick={() => {
                onChange?.(draft);
                setOpen(false);
              }}
            >
              Apply
            </Button>
          </div>
        </PopoverContent>
      </Popover>
    );
  },
);
DateRangePicker.displayName = "DateRangePicker";

export { DateRangePicker };

"use client";

import * as React from "react";
import * as DialogPrimitive from "@radix-ui/react-dialog";
import { AnimatePresence, motion, type Transition } from "framer-motion";
import { X } from "lucide-react";

import { cn } from "@blocks/ui/lib/utils";

const DialogOpenContext = React.createContext<boolean>(false);

type DialogRootProps = React.ComponentProps<typeof DialogPrimitive.Root>;

const Dialog = ({
  open: openProp,
  defaultOpen,
  onOpenChange,
  children,
  ...props
}: DialogRootProps) => {
  const [uncontrolled, setUncontrolled] = React.useState<boolean>(defaultOpen ?? false);
  const isControlled = openProp !== undefined;
  const open = isControlled ? (openProp ?? false) : uncontrolled;

  const handleOpenChange = React.useCallback(
    (next: boolean) => {
      if (!isControlled) setUncontrolled(next);
      onOpenChange?.(next);
    },
    [isControlled, onOpenChange],
  );

  return (
    <DialogPrimitive.Root open={open} onOpenChange={handleOpenChange} {...props}>
      <DialogOpenContext.Provider value={open}>{children}</DialogOpenContext.Provider>
    </DialogPrimitive.Root>
  );
};

const DialogTrigger = DialogPrimitive.Trigger;
const DialogPortal = DialogPrimitive.Portal;
const DialogClose = DialogPrimitive.Close;

const overlayTransition: Transition = { duration: 0.18, ease: [0.4, 0, 0.2, 1] };
const contentTransition: Transition = { duration: 0.22, ease: [0.16, 1, 0.3, 1] };

const DialogOverlay = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Overlay>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Overlay>
>(({ className, ...props }, ref) => (
  <DialogPrimitive.Overlay ref={ref} forceMount asChild {...props}>
    <motion.div
      className={cn("fixed inset-0 z-50 bg-black/60 backdrop-blur-sm", className)}
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      transition={overlayTransition}
    />
  </DialogPrimitive.Overlay>
));
DialogOverlay.displayName = DialogPrimitive.Overlay.displayName;

const DialogContent = React.forwardRef<
  React.ComponentRef<typeof DialogPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DialogPrimitive.Content>
>(({ className, children, ...props }, ref) => {
  const open = React.useContext(DialogOpenContext);
  return (
    <AnimatePresence>
      {open ? (
        <DialogPortal forceMount>
          <DialogOverlay />
          <DialogPrimitive.Content ref={ref} forceMount asChild {...props}>
            <motion.div
              className={cn(
                "fixed left-1/2 top-1/2 z-50 grid w-full max-w-lg -translate-x-1/2 -translate-y-1/2 gap-4 border bg-background p-6 shadow-lg sm:rounded-lg",
                className,
              )}
              initial={{ opacity: 0, scale: 0.96, y: 8 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.97, y: 6 }}
              transition={contentTransition}
            >
              {children}
              <DialogPrimitive.Close className="absolute right-4 top-4 rounded-sm opacity-70 ring-offset-background transition-opacity hover:opacity-100 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-2 disabled:pointer-events-none data-[state=open]:bg-accent data-[state=open]:text-muted-foreground">
                <X className="h-4 w-4" />
                <span className="sr-only">Close</span>
              </DialogPrimitive.Close>
            </motion.div>
          </DialogPrimitive.Content>
        </DialogPortal>
      ) : null}
    </AnimatePresence>
  );
});
DialogContent.displayName = DialogPrimitive.Content.displayName;

const DialogHeader = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div
